"""Bind complete original short-normal set to separately proved direct roots."""
from pathlib import Path
import csv,gzip,json,hashlib,collections
R=Path(__file__).resolve().parent;sha=hashlib.sha256((R/'model.stl').read_bytes()).hexdigest();b=json.loads((R/'local-back-roots.json').read_text());c=json.loads((R/'corner-root-check.json').read_text());assert b['stl_sha256']==c['stl_sha256']==sha
key=lambda r:(r['face'],r['sample']);bad={key(r) for r in b['arch_transition_exclusions']};back=[r for r in b['samples'] if key(r) not in bad];corn=c['samples'];bk={key(r) for r in back};ck={key(r) for r in corn};short={(int(r['face']),int(r['sample'])) for r in csv.DictReader(gzip.open(R/'dense-samples.csv.gz','rt')) if float(r['first_solid'])<.8}
checks={'every_original_short_sample_classified_once':not (bk&ck) and bk|ck==short,'all_backing_roots_ge_0p8_and_controls_inside':all(r['backing_direction_first_solid_mm']>=.8 and all(r['near_root_inside_controls']) for r in back),'all_remaining_actual_face_cone_roots_accepted':all(r['accepted_local_corner_root'] for r in corn),'all_arch_transition_exclusions_in_corner_review':bad<=ck};assert all(checks.values())
g=collections.defaultdict(list)
for r in corn:g[len(r['attempts'][-1]['face_planes'])].append(r['attempts'][-1])
summary={str(k):{'samples':len(v),'minimum_direct_first_root_mm':min(r['first_solid_mm'] for r in v),'maximum_plane_intersection_distance_mm':max(r['distance_to_actual_plane_intersection_mm'] for r in v),'maximum_inward_dot':max(max(r['dot_with_each_actual_outward_normal']) for r in v)} for k,v in g.items()}
(R/'family-coverage.json').write_text(json.dumps({'stl_sha256':sha,'passed':True,'checks':checks,'original_short_samples':len(short),'backed_samples':len(back),'minimum_backing_root_mm':min(r['backing_direction_first_solid_mm'] for r in back),'actual_face_cone_samples':len(corn),'cone_groups':summary,'retained_failed_intermediate_cone_directions':sum(len(r['attempts'])-1 for r in corn),'limits':'Complete finite original seven-point sampling set only, not all points/all directions or proof of physical print strength. The original normal short lengths, later air gaps and failed intermediate directions remain public.'},indent=2));print(summary)
